//! 🧷️ Native catalog queries borrow exact original slots under every funded continuation frontier.
use super::*;
use semio_framework_plugin::app_testing::OriginalWorkFixture;
use semio_framework_value::RetainedCloneGrant;
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcSnapshot,IfcEntity,IfcComplexType,IfcValue};
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:0,maximum_release_bytes:65536,maximum_depth:8}}
fn source(row:&serde_json::Value)->IfcSnapshot{let values=|row:&serde_json::Value|row["args"].as_array().unwrap().iter().map(|value|IfcValue::String(value.as_str().unwrap().into())).collect();let mut entities=(0..7).map(|id|IfcEntity{id,name:"IFCREPRESENTATIONITEM".into(),args:vec![],complex:vec![]}).collect::<Vec<_>>();let entity=&row["entity"];entities.push(IfcEntity{id:71,name:entity["name"].as_str().unwrap().into(),args:values(entity),complex:entity["complex"].as_array().map_or_else(Vec::new,|parts|parts.iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:values(part)}).collect())});IfcSnapshot{entities,..Default::default()}}
fn status(value:IfcAttributeQueryStatus)->&'static str{match value{IfcAttributeQueryStatus::Missing=>"missing",IfcAttributeQueryStatus::Unique=>"unique",IfcAttributeQueryStatus::Ambiguous=>"ambiguous",IfcAttributeQueryStatus::Unknown=>"unknown"}}
fn close(work:&mut IfcAttributeQueryWork,caller:&mut OriginalWorkFixture){for _ in 0..8{if work.terminal_is_empty(){return;}caller.turn(grant(),|cx|cx.with_original_retirement(|cx|work.close_step(cx))).unwrap();}panic!("original query metadata did not close")}
#[test]
fn neutral_attribute_queries_borrow_owner_qualified_source_slots_and_static_declarations(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/cases.json")).unwrap();
    for row in fixture["cases"].as_array().unwrap(){let snapshot=source(row);let name=row["name"].as_str().unwrap();let owner=row["owner"].as_str();let mut caller=OriginalWorkFixture::new();let mut work=IfcAttributeQueryWork::default();let mut complete=false;
        for _ in 0..10000{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,name,owner,31,cx)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if result.unwrap(){complete=true;break;}}assert!(complete);
        let(found,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(grant(),1,|cx|Ok(work.completed::<Ifc4x3AttributeMetadata,_>(&snapshot,7,name,owner,31,cx)?)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let found=found.unwrap().unwrap();assert_eq!(status(found.status),row["status"].as_str().unwrap());let matches=found.matches.iter().flatten().collect::<Vec<_>>();assert_eq!(matches.len(),row["values"].as_array().unwrap().len());for(index,entry)in matches.iter().enumerate(){let Some(IfcValue::String(value))=entry.value else{panic!("actual fixture marker missing")};assert_eq!(value,row["values"][index].as_str().unwrap());assert_eq!(entry.address.to_string(),row["pointers"][index].as_str().unwrap());let part=if entry.address.part==0{snapshot.entities[7].args.as_slice()}else{snapshot.entities[7].complex[entry.address.part-1].args.as_slice()};assert!(std::ptr::eq(entry.value.unwrap(),&part[entry.address.index]));let entity=crate::validation::metadata::entity(if entry.address.part==0{&snapshot.entities[7].name}else{&snapshot.entities[7].complex[entry.address.part-1].name}).unwrap();let attributes=if snapshot.entities[7].complex.is_empty(){entity.all_attributes}else{entity.attributes};assert!(std::ptr::eq(entry.declaration,&attributes[entry.address.index]));assert!(std::ptr::eq(entry.type_expr,&entry.declaration.type_expr));assert!(entry.declaration.declared_by.eq_ignore_ascii_case(owner.unwrap()));}close(&mut work,&mut caller);caller.finish();
    }
}
#[test]
fn query_grants_and_original_source_request_profile_are_stationary(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/cases.json")).unwrap();let snapshot=source(&fixture["cases"][0]);let other=snapshot.clone();let name=String::from("Position");let replacement=name.clone();let owner=Some("IFCPARAMETERIZEDPROFILEDEF");let mut caller=OriginalWorkFixture::new();let mut work=IfcAttributeQueryWork::default();
    for _ in 0..512{if caller.work_turn(grant(),1,|cx|Ok(work.completed::<Ifc4x3AttributeMetadata,_>(&snapshot,7,&name,owner,31,cx)?.is_some())).unwrap(){break;}let demand=work.demands();for axis in 0..4{let mut denied=grant();match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=demand.copy_bytes-1,2=>denied.maximum_depth=0,_=>{}}let before=format!("{work:?}");let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,if axis==3{0}else{1},|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,&name,owner,31,cx)));assert!(!result.unwrap());assert_eq!(format!("{work:?}"),before);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,&name,owner,31,cx)).unwrap();}
    for mode in 0..4{let before=format!("{work:?}");let result=caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(if mode==0{&other}else{&snapshot},if mode==1{6}else{7},if mode==2{&replacement}else{&name},owner,if mode==3{32}else{31},cx));assert!(result.is_err());assert_eq!(format!("{work:?}"),before);}let mut foreign=OriginalWorkFixture::new();assert!(foreign.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,&name,owner,31,cx)).is_err());foreign.finish();close(&mut work,&mut caller);caller.finish();
}
#[test]
fn missing_values_and_unqualified_queries_do_not_claim_domain_admission(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/cases.json")).unwrap();let mut snapshot=source(&fixture["cases"][0]);snapshot.entities[7].args.clear();let mut work=IfcAttributeQueryWork::default();let mut caller=OriginalWorkFixture::new();for _ in 0..1000{if caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,"XDim",None,31,cx)).unwrap(){break;}}caller.work_turn(grant(),1,|cx|{let result=work.completed::<Ifc4x3AttributeMetadata,_>(&snapshot,7,"XDim",None,31,cx)?.unwrap();assert_eq!(result.status,IfcAttributeQueryStatus::Unique);assert!(result.matches[0].as_ref().unwrap().value.is_none());assert_eq!(result.matches[0].as_ref().unwrap().address.to_string(),"/entities/7/args/3");Ok(())}).unwrap();close(&mut work,&mut caller);caller.finish();
}
#[test]
fn every_query_prefix_cancels_without_results_and_retires_under_original_context(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/cases.json")).unwrap();let row=fixture["cases"].as_array().unwrap().iter().find(|row|row["id"]=="unknown-after-duplicates").unwrap();let snapshot=source(row);let name=row["name"].as_str().unwrap();let owner=row["owner"].as_str();let mut total=0;
    {let mut caller=OriginalWorkFixture::new();let mut work=IfcAttributeQueryWork::default();while !caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,name,owner,31,cx)).unwrap(){total+=1;assert!(total<10000);}close(&mut work,&mut caller);caller.finish();}
    for prefix in 0..=(total+1){let mut caller=OriginalWorkFixture::new();let mut work=IfcAttributeQueryWork::default();for _ in 0..prefix{caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,name,owner,31,cx)).unwrap();}let before=format!("{work:?}");caller.cancel().cancel_now();assert!(caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,name,owner,31,cx)).is_err());assert_eq!(format!("{work:?}"),before);assert!(caller.work_turn(grant(),1,|cx|Ok(work.completed::<Ifc4x3AttributeMetadata,_>(&snapshot,7,name,owner,31,cx)?)).is_err());close(&mut work,&mut caller);caller.finish();}
}

struct AlternateMetadata;
impl IfcAttributeQueryMetadata for AlternateMetadata{type Attribute=crate::validation::metadata::StaticAttribute;type Expression=crate::validation::metadata::StaticTypeExpression;fn attributes(name:&str,direct:bool)->Option<IfcQueryAttributes<Self::Attribute>>{Ifc4x3AttributeMetadata::attributes(name,direct)}fn name(attribute:&'static Self::Attribute)->&'static str{attribute.name}fn declared_by(attribute:&'static Self::Attribute)->&'static str{attribute.declared_by}fn type_expr(attribute:&'static Self::Attribute)->&'static Self::Expression{&attribute.type_expr}}
#[test]
fn invalid_identifiers_indices_and_a_different_metadata_profile_never_become_unique_values(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/cases.json")).unwrap();let snapshot=source(&fixture["cases"][0]);
    for name in [String::new(),"7Position".into(),"Position.".into(),"Positión".into(),"A".repeat(257)]{let mut work=IfcAttributeQueryWork::default();let mut caller=OriginalWorkFixture::new();let mut ready=false;for _ in 0..2000{if caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,&name,None,31,cx)).unwrap(){ready=true;break;}}assert!(ready);caller.work_turn(grant(),1,|cx|{let result=work.completed::<Ifc4x3AttributeMetadata,_>(&snapshot,7,&name,None,31,cx)?.unwrap();assert_eq!(result.status,IfcAttributeQueryStatus::Unknown);assert!(result.matches.iter().all(Option::is_none));Ok(())}).unwrap();close(&mut work,&mut caller);assert!(caller.work_turn(grant(),1,|cx|Ok(work.completed::<Ifc4x3AttributeMetadata,_>(&snapshot,7,&name,None,31,cx)?)).is_err());caller.finish();}
    let mut caller=OriginalWorkFixture::new();let mut work=IfcAttributeQueryWork::default();caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,7,"Position",None,31,cx)).unwrap();let before=format!("{work:?}");assert!(caller.work_turn(grant(),1,|cx|work.advance::<AlternateMetadata,_>(&snapshot,7,"Position",None,31,cx)).is_err());assert_eq!(format!("{work:?}"),before);close(&mut work,&mut caller);caller.finish();
    let mut caller=OriginalWorkFixture::new();let mut work=IfcAttributeQueryWork::default();let mut refused=false;for _ in 0..1000{if caller.work_turn(grant(),1,|cx|work.advance::<Ifc4x3AttributeMetadata,_>(&snapshot,usize::MAX,"Position",None,31,cx)).is_err(){refused=true;break;}}assert!(refused);close(&mut work,&mut caller);caller.finish();
}
